import{_ as p,o as e,c as s,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const b=JSON.parse('{"title":"末端电容的反射","description":"","frontmatter":{},"headers":[],"relativePath":"notes/《信号完整性》学习笔记/18-末端电容的反射.md","filePath":"notes/《信号完整性》学习笔记/18-末端电容的反射.md","lastUpdated":1794138465000}'),c={name:"notes/《信号完整性》学习笔记/18-末端电容的反射.md"};function r(l,a,n,d,o,i){return e(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="末端电容的反射" tabindex="-1">末端电容的反射 <a class="header-anchor" href="#末端电容的反射" aria-label="Permalink to &quot;末端电容的反射&quot;">​</a></h1><h2 id="一问题提出与仿真设置" tabindex="-1">一、问题提出与仿真设置 <a class="header-anchor" href="#一问题提出与仿真设置" aria-label="Permalink to &quot;一、问题提出与仿真设置&quot;">​</a></h2><p>当容性阻抗处在传输线的末端、信号的上升时间又不是零的时候，这个电容的反射特性是什么样子?它对波形造成的影响又是什么样子?</p><p>最直观的办法，就是直接通过原理性的仿真来观察。 建立一个仿真原理图，用不同的上升时间做几个实验：</p><p>第一个 TR1，上升时间为零，也就是理想方波；</p><p>第二个是 400 ps；</p><p>第三个是 800 ps。</p><p>观察一下不同上升时间的情况下，反射波形分别是什么样子。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794110751870-bb4b2bf6-c87a-4e5f-aeb2-fbae677fda83.svg" alt="TR1 仿真电路（上升时间 0 ps，理想方波）"></p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794110752415-19f1e5a7-acb7-48e1-b0f6-eb785266c6dc.svg" alt="TR2 仿真电路（上升时间 400 ps）"></p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794110753083-dd6da23c-2f0e-474a-bcb2-0231a765882a.svg" alt="TR3 仿真电路（上升时间 800 ps）"></p><h2 id="二传输线入口的凹陷波形" tabindex="-1">二、传输线入口的凹陷波形 <a class="header-anchor" href="#二传输线入口的凹陷波形" aria-label="Permalink to &quot;二、传输线入口的凹陷波形&quot;">​</a></h2><p>TR1 的入射信号上升时间是零，也就是理想方波。它经过末端电容反射之后，在传输线入口这个位置，电容反射波形回来之后叠加在入射信号上。 如果信号的上升时间是零，那么电容的反射会一下子把电压拉到零。但是，当信号的上升时间不是零的时候（实际的信号都需要一段时间来爬升），波形就变成蓝色曲线这个样子——注意，这仍是传输线入口那个位置，不是末端。</p><p>也就是说，电容反射回来之后，叠加在入射信号上，在走线起始端形成这样一个波形：</p><p>它的最低点没有降到零幅，缓慢地下来之后，过一段时间又上去了，出现了一个小的凹陷。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794117484804-871b0102-f660-429b-9b4c-177ec5390f8b.svg" alt="传输线入口波形：上升时间为零时电容反射把电压拉到零（红），上升时间不为零时形成未到零的小凹陷（蓝）"></p><p>再看末端电容那个位置。</p><p>当上升时间为零的时候，这条红色曲线其实就是电容充电时电压变化的曲线；而这条蓝色曲线也是电容充电的曲线。只不过给电容充电的入射信号不是突然间加上一个电压，而是缓慢地施加，施加的电压也在缓慢变化，电容本身也在充电，两者叠加在一起。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794120997638-a4654e26-a481-484c-9092-320c26df54be.svg" alt="末端电容两端的电压波形：上升时间为零时是标准充电曲线（红），上升时间不为零时是信号爬升与充电叠加（蓝）"></p><h2 id="三凹陷波形的成因" tabindex="-1">三、凹陷波形的成因 <a class="header-anchor" href="#三凹陷波形的成因" aria-label="Permalink to &quot;三、凹陷波形的成因&quot;">​</a></h2><p>首先，末端是电容、上升时间不为零时，把这个波形模拟出来；然后看电容充电时、上升时间不为零，电容两端电压的变化曲线是什么样子。 因为传输线的延迟是一个纳秒，把这个电容充电的波形往后挪两个纳秒，实际上就相当于信号入射、再反射回来，在传输线入口的位置看到的结果。</p><p>如果末端不是电容，而是理想的短路，那么在传输线入口这个位置，电压波形会是什么样子？</p><p>末端是理想短路的时候，传输线到达末端，会发生负反射，信号的负反射，反射的是波形本身，而负反射事实上波形跳变的状态变了。 信号经过一个纳秒到末端，负反射这个波形再经过一个纳秒，到达传输线入口；也就是说，经过两个纳秒之后，反射波形和入射波形叠加，把入口电压拖到零幅。</p><p>信号上升时间是 400 ps 的时候，也是拖到零。波形上有一个弯曲的拐点，拐点之后非常像电容充电的曲线。当信号经过了一个信号上升时间之后，后面的曲线就是末端电容的充电曲线；而在信号上升时间这一段范围之内，出现了一个小的凹陷。如果信号是理想方波，上升时间是零，那么它一下子就拉到零；如果不是零，就出现一个小的凹槽。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794124604509-a4a70519-821b-41b2-ae69-cada60932a1a.svg" alt="末端理想短路（入口电压 2 ns 后拖到零）与上升时间 400 ps（入口出现小凹陷、之后为电容充电曲线）的对比"></p><p>粉红色这条线是末端短路的时候，发生负反射、在传输线入口的位置观察到的电压波形；</p><p>而红色这条线，就是信号上升时间不为零的时候，在传输线起始端入口位置，看到的信号的波形。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794128683706-f16dc51e-8c62-46e1-bcff-15974fa9ab6b.svg" alt="末端短路的反射与上升时间 Tr：粉红色为短路时的入口电压波形，红色为上升时间不为零时的入口波形，蓝色虚线为电容的电压变化"></p><p>为什么一直在强调传输线入口这个位置看到的波形？</p><p>因为研究反射的时候，在传输线入口那个位置看到的波形是包含反射的。所以说观察这个波形，就能观察到反射特性到底是什么样。</p><h2 id="四凹陷深度与信号上升时间的关系" tabindex="-1">四、凹陷深度与信号上升时间的关系 <a class="header-anchor" href="#四凹陷深度与信号上升时间的关系" aria-label="Permalink to &quot;四、凹陷深度与信号上升时间的关系&quot;">​</a></h2><p>先来看信号上升时间不同的实验结果。</p><p>信号上升时间分别是零、四百个皮秒、八百个皮秒：</p><ul><li>信号上升时间为零的时候，它马上给你拉到零，然后后面就是电容的充电曲线。</li><li>信号上升时间是四百个皮秒的时候，在信号上升时间范围之内，信号也向下凹陷，但是没凹陷到零；然后信号上升结束、信号达到稳态，后面就是电容的充电波形了。</li><li>信号上升时间是八百皮秒的时候，它是经过八百皮秒之后，后面是电容的充电波形。</li></ul><p>凹陷能向下多少，和信号上升时间有关：</p><p>信号边沿越陡峭，容性负载所引起的反射、引起的噪声就越大。</p><p>信号上升时间是零的时候，反射最大。</p><p>信号上升时间越短，容性负载的反射所引起的凹陷就越低。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794130573818-53e749ef-21d6-4f88-a529-9fa442d8c3e0.svg" alt="入口波形随上升时间变化：0 ps 拉到零，400 ps / 800 ps 凹陷逐渐变浅"></p><p>再看末端的这个波形。</p><p>信号上升时间不同的时候，电容充电的波形，是加载到电容两端的信号波形形状、还有电容充电特性，这两者综合起来的结果。</p><p>信号上升时间是零的时候，红色的是标准的电容充电的指数上升曲线。</p><p>上升时间不是零的时候，信号会发生变形，电容充电还要考虑信号在缓慢爬升，两者综合作用。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794135048366-cb32351d-bde1-41ea-bec5-6187ff291ef8.svg" alt="末端电容两端电压随上升时间变化：零为指数充电曲线，非零为信号爬升与充电叠加"></p><h2 id="五凹陷深度与末端电容量的关系" tabindex="-1">五、凹陷深度与末端电容量的关系 <a class="header-anchor" href="#五凹陷深度与末端电容量的关系" aria-label="Permalink to &quot;五、凹陷深度与末端电容量的关系&quot;">​</a></h2><p>这一组上升时间都是四百个皮秒，末端电容不同：两个皮法、四个皮法、八个皮法。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794136981898-4bef3cdb-9db3-4e45-89b6-2b1913d81f13.svg" alt="C1 仿真电路（末端电容 2 pF，上升时间 400 ps）"></p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794136982478-b4d239f9-0e8a-443c-8a8a-3cb8c4e12656.svg" alt="C2 仿真电路（末端电容 4 pF，上升时间 400 ps）"></p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794136983098-c4a91702-40c2-4b1c-a471-d192b7967b3f.svg" alt="C3 仿真电路（末端电容 8 pF，上升时间 400 ps）"></p><p>也是观察传输线入口这个位置，因为传输线入口的波形包含了信号反射的波形。</p><p>上升时间都是四百个皮秒，末端电容是两皮法、四个皮法、八个皮法。</p><p>电容越大，容性负载越大，反射就越厉害，凹陷就越多，说明反射噪声越大。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794136983860-6e7b4cf7-7c75-4301-af16-09743fc6c85f.svg" alt="入口波形随末端电容变化（上升时间均 400 ps）：2 pF / 4 pF / 8 pF，电容越大凹陷越深"></p><h2 id="六容性负载反射的行为特征" tabindex="-1">六、容性负载反射的行为特征 <a class="header-anchor" href="#六容性负载反射的行为特征" aria-label="Permalink to &quot;六、容性负载反射的行为特征&quot;">​</a></h2><p>那么末端电容的反射，就是这个样子：</p><p>当信号有一定的爬升时间的时候，不能按照理想的那种方法去分析了——它有一定的爬升时间的时候，反射波形的形状也会发生变化。</p><p>最关键的，是了解它的这种行为特征。</p>',57)])])}const u=p(c,[["render",r]]);export{b as __pageData,u as default};
